INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-1', 'merchant-1', 'category-jackets', 'Black Washed Zip-Up Jacket', 'جاكيت أسود مغسول بسوستة', 'An oversized black zip jacket with shirt collar and ribbed cuffs for daily wear.', 'جاكيت أسود أوفرسايز بسوستة بياقة قميص وأساور أستك للبس كل يوم.', 'An oversized black long-sleeve zip-up jacket in lightweight washed fabric with a pointed shirt collar, full front zip closure, two lower flap pockets with snap buttons, and ribbed knit cuffs and hem.', 'UNISEX', 'ACTIVE', 100000, '/products/product-1-1.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-2', 'merchant-1', 'category-hoodies', 'Beige Cropped Fleece Hoodie', 'هودي بيج فليس قصير', 'Soft cream-beige fleece hoodie with drawstring hood and kangaroo pocket for cozy everyday wear.', 'هودي بيج فاتح بخامة فليس ناعمة وجيب قدام وغطا راس برباط، حلو للبس اليومي المريح.', 'A cream-beige pullover hoodie in soft fleece sweatshirt fabric with a relaxed slightly cropped cut, drawstring hood, long sleeves with ribbed cuffs, front kangaroo pocket, and ribbed hem.', 'UNISEX', 'ACTIVE', 55000, '/products/product-1-2.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-3', 'merchant-1', 'category-sweatshirts', 'Navy Oversized Crewneck Sweatshirt', 'سويت شيرت كحلي أوفرسايز برقبة دائرية', 'Soft navy oversized sweatshirt with ribbed trims, perfect for everyday casual wear.', 'سويت شيرت كحلي أوفرسايز بخامة ناعمة وأستك على الرقبة والكم، مناسب للبس اليومي الكاجوال.', 'Navy blue oversized long-sleeve crewneck sweatshirt in soft sweatshirt knit fabric with dropped shoulders, ribbed round neckline, ribbed cuffs and hem, and a plain front with no graphics.', 'UNISEX', 'ACTIVE', 55000, '/products/product-1-3.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-4', 'merchant-1', 'category-knitwear', 'Olive Cropped Textured Knit Sweater', 'سويتر زيتي كروب تريكو بارز', 'Cropped olive sweater in soft textured knit with ribbed trims, perfect for casual daily wear.', 'سويتر زيتي كروب بخامة تريكو ناعمة ولمسة مضلعة مناسب للبس اليومي الكاجوال', 'Olive green cropped long-sleeve crew-neck sweater in soft textured knit fabric with a relaxed fit and ribbed detailing at the neckline, cuffs, and hem.', 'UNISEX', 'ACTIVE', 80000, '/products/product-1-4.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-5', 'merchant-1', 'category-jeans', 'Burgundy Baggy Barrel-Leg Jeans', 'جينز نبيتي باجي واسع', 'High-waisted burgundy jeans with a loose barrel leg and button closure for easy daily wear.', 'جينز نبيتي عالي الوسط برجل برميل واسعة وبزرار من قدام ينفع للخروجات اليومية', 'High-waisted baggy jeans in deep burgundy denim with a loose barrel-leg cut, five-pocket styling, belt loops and a button-front closure.', 'UNISEX', 'ACTIVE', 100000, '/products/product-1-5.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-6', 'merchant-1', 'category-pants', 'Grey Linen Cropped Pants', 'بنطلون رمادي كتان قصير', 'Light grey cropped trousers in textured linen-like fabric with a tapered fit for daily summer wear.', 'بنطلون رمادي فاتح قصير بخامة شبه الكتان وقصة مظبوطة ينفع للبس اليومي في الصيف.', 'Light gray flat-front cropped trousers with a straight tapered cut in a textured linen-like fabric featuring belt loops, slanted side pockets, and a front fly closure.', 'MEN', 'ACTIVE', 45000, '/products/product-1-6.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-7', 'merchant-1', 'category-dresses', 'Brown Linen Shirt Dress', 'فستان قميص كتان بني', 'Oversized brown linen shirt dress with collar, buttons and side pockets for comfortable daily outings.', 'فستان قميص بني كتان واسع بزراير وجيوب جانبية مريح للخروجات اليومية.', 'A loose oversized brown linen midi shirt dress with a collared neckline, full front button closure, long wide sleeves with cuffs, and two side seam pockets.', 'WOMEN', 'ACTIVE', 90000, '/products/product-1-7.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-8', 'merchant-1', 'category-skirts', 'Cream Pleated Linen Mini Skirt', 'جيبة ميني كريمي بليسيه كتان', 'High-waisted cream pleated mini skirt with pockets, easy to wear for daily outings.', 'جيبة كريمي قصيرة بوسط عالي وكسرات وجيوب تنفع لخروجات كل يوم.', 'Off-white high-waisted pleated mini skirt in textured linen-like fabric with a wide waistband, belt loops, front pleats, side slant pockets, and a visible back zip.', 'WOMEN', 'ACTIVE', 55000, '/products/product-1-8.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-9', 'merchant-1', 'category-shoes', 'Black Leather Mesh Sneakers', 'كوتشي أسود جلد وميش', 'Black low-top lace-up sneakers in leather and mesh with a thick sole, good for everyday wear.', 'كوتشي أسود برقبة واطية برباط من الجلد والميش بنعل تخين، ينفع للبس كل يوم.', 'Black low-top lace-up chunky sneaker made of smooth leather overlays and breathable mesh with black laces and a thick textured sole.', 'UNISEX', 'ACTIVE', 125000, '/products/product-1-9.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-1-10', 'merchant-1', 'category-bags', 'Beige Canvas Tassel Flap Bag', 'شنطة بيج كانفس بقلاب بشرابة', 'Small beige canvas flap bag with snap closure and side tassels for everyday outings.', 'شنطة بيج صغيرة قماشها كانفس بقلاب وزرار كبس وشراشيب من الجنب تنفع لمشاوير كل يوم', 'Small beige rectangular canvas flap bag with rounded corners, front snap-button closure, stitched edging, and gold-tone side clasps with beige tassel pulls.', 'WOMEN', 'ACTIVE', 25000, '/products/product-1-10.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-1', 'merchant-2', 'category-jackets', 'Black Two-Button Tailored Jacket', 'جاكيت أسود كلاسيك بزراير', 'Black tailored blazer with notched lapels and two buttons, ideal for work and evening events.', 'جاكيت أسود مظبوط بياقة كلاسيك وزرارين، تلبسه في الشغل والمناسبات الرسمية.', 'A black single-breasted tailored blazer in smooth matte fabric with notched lapels, two-button front closure, long sleeves, and two front flap pockets.', 'UNISEX', 'ACTIVE', 45000, '/products/product-2-1.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-2', 'merchant-2', 'category-sweatshirts', 'Burgundy Relaxed Fleece Sweatshirt', 'سويت شيرت عنابي فليس مريح', 'A relaxed burgundy crewneck sweatshirt in soft fleece with ribbed trims for daily casual wear.', 'سويت شيرت عنابي سادة بقصة مريحة وخامة فليس ناعمة مناسب للبس كل يوم.', 'A solid burgundy crewneck sweatshirt in a relaxed long-sleeve cut made of soft fleece-like fabric with ribbed detailing at the neckline, cuffs, and hem.', 'UNISEX', 'ACTIVE', 35000, '/products/product-2-2.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-3', 'merchant-2', 'category-knitwear', 'Grey Fine Knit Crewneck Sweater', 'سويتر رمادي تريكو ناعم برقبة كرو', 'Gray long-sleeve crewneck sweater with ribbed edges for everyday casual wear.', 'سويتر رمادي بكم طويل ورقبة كرو وأطراف مضلعة، مناسب للبس كل يوم.', 'A heather gray long-sleeve crewneck pullover sweater in a regular cut made of fine-knit fabric with ribbed trim at the neckline, cuffs, and hem.', 'UNISEX', 'ACTIVE', 60000, '/products/product-2-3.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-4', 'merchant-2', 'category-jeans', 'Brown Corduroy Straight-Leg Jeans', 'بنطلون جينز بني قطيفة برجل عدلة', 'Brown high-rise corduroy pants with a straight leg and button closure for daily casual wear.', 'بنطلون بني قطيفة مضلع بوسط عالي ورجل عدلة وقفلة زرار ينفع تلبسه كل يوم.', 'Brown straight-leg corduroy pants with a high-rise waist, five-pocket styling, front button closure, belt loops, and fine ribbed texture.', 'UNISEX', 'ACTIVE', 80000, '/products/product-2-4.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-5', 'merchant-2', 'category-pants', 'Cream Pleated Cotton Pants', 'بنطلون كريمي قطن بكسرات', 'Soft cream pleated trousers with a high waist, perfect for daily wear and work.', 'بنطلون كريمي مريح بخامة قطن وكسرات ووسط عالي، حلو للبس اليومي والشغل.', 'Off-white pleated straight tapered trousers in soft cotton fabric with a high waist, single-button closure, belt loops, slanted side pockets, and pressed front creases.', 'MEN', 'ACTIVE', 70000, '/products/product-2-5.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-6', 'merchant-2', 'category-dresses', 'Black Cable-Knit Turtleneck Dress', 'فستان أسود تريكو مضفر برقبة عالية', 'Long-sleeve black cable-knit midi dress with turtleneck and front pockets for cold weather outings.', 'فستان ميدي اسود تريكو مضفر بكم طويل ورقبة عالية وجيوب قدام للخروج في البرد.', 'A black long-sleeve turtleneck knit midi sweater dress in chunky cable-knit fabric with vertical cable patterns, ribbed collar, cuffs and hem, and two front patch pockets.', 'WOMEN', 'ACTIVE', 115000, '/products/product-2-6.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-7', 'merchant-2', 'category-skirts', 'Beige Pleated Pocket Midi Skirt', 'جيبة بيج ميدي بكسرات وجيوب', 'Beige midi pencil skirt with front pleats and side pockets, good for work and everyday wear.', 'جيبة بيج ميدي بقصة قلم رصاص وكسرات من قدام وجيوب جانبية تنفع للشغل والخروجات اليومية', 'A beige high-waisted midi pencil skirt in smooth cotton-twill-like fabric with front waist pleats, belt loops, slanted side pockets, a single button closure and a front center seam.', 'WOMEN', 'ACTIVE', 35000, '/products/product-2-7.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-8', 'merchant-2', 'category-shoes', 'Navy Knit Shearling Collar Sneakers', 'كوتشي كحلي تريكو برقبة فرو', 'Navy low-top knit sneakers with a light fuzzy collar for everyday casual wear.', 'كوتشي كحلي برقبة فرو فاتحة وخامة تريكو تلبسه في المشاوير اليومية.', 'Front view of a navy blue low-top lace-up sneaker with a ribbed knit fabric upper, cream faux-shearling collar lining, matching navy laces, and a dark rubber sole.', 'UNISEX', 'ACTIVE', 105000, '/products/product-2-8.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-2-9', 'merchant-2', 'category-bags', 'Olive Pebbled Push-Lock Bag', 'شنطة زيتوني محببة بقفل كبس', 'Structured olive handbag in pebbled leather with a curved flap and gold clasp for work and daily outings.', 'شنطة زيتوني ناشفة بخامة جلد محببة وغطا مقوس وقفل دهبي تنفع للشغل والمشاوير اليومية.', 'Olive green structured rectangular top-handle handbag in pebbled leather with a curved front flap and gold-tone push-lock clasp.', 'WOMEN', 'ACTIVE', 50000, '/products/product-2-9.jpg');
