INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-2', 'merchant-19', 'category-bags', 'Cream Quilted Puffer Tote Bag', 'شنطة توت باف كريمي مبطنة', 'Oversized cream puffer tote with vertical quilting and padded handles for daily use.', 'شنطة توت باف كبيرة لونها كريمي بخياطة طولية ودراعات مبطنة تنفع للخروج اليومي.', 'An oversized cream-colored puffer tote bag in soft quilted padded fabric with vertical channel stitching and thick padded shoulder handles.', 'WOMEN', 'ACTIVE', 35000, '/products/product-19-2.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-3', 'merchant-19', 'category-jackets', 'Black Bomber Jacket', 'جاكيت بومبر اسود', 'Cropped black bomber with stand collar and zip pockets for casual daily outings.', 'جاكيت بومبر اسود قصير بياقة واقفة وجيوب بسوستة للخروجات اليومية.', 'A black bomber jacket with stand collar, full front zipper, long sleeves with ribbed cuffs, cropped relaxed fit in smooth matte fabric with ribbed hem and two diagonal zippered front pockets.', 'UNISEX', 'ACTIVE', 90000, '/products/product-19-3.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-4', 'merchant-19', 'category-hoodies', 'Beige Drop-Shoulder Kangaroo Hoodie', 'هودي بيج بكتف ساقط وجيب كنغر', 'A light beige relaxed pullover hoodie with a drawstring hood and kangaroo pocket for everyday casual wear.', 'هودي بيج فاتح ومريح بغطا راس برباط وجيب كنغر تلبسيه كل يوم في المشاوير الكاجوال.', 'A light beige relaxed-fit pullover hoodie in soft fleece sweatshirt fabric with a drawstring hood, front kangaroo pocket, long drop-shoulder sleeves with ribbed cuffs, and a ribbed hem.', 'UNISEX', 'ACTIVE', 75000, '/products/product-19-4.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-5', 'merchant-19', 'category-sweatshirts', 'Navy Cropped Fleece Sweatshirt', 'سويت شيرت كحلي كروب فليس', 'Cropped navy sweatshirt with raglan sleeves and ribbed trims for easy daily wear.', 'سويت شيرت كحلي قصير بكم رجلان وريب مضلع تلبسيه في المشاوير اليومية.', 'A navy blue cropped crewneck sweatshirt with long raglan sleeves made of soft fleece fabric featuring a ribbed neckline, cuffs, and hem.', 'UNISEX', 'ACTIVE', 75000, '/products/product-19-5.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-6', 'merchant-19', 'category-knitwear', 'Olive Textured Oversized Sweater', 'بلوفر زيتي تريكو أوفرسايز', 'Oversized olive knit sweater with ribbed trims, perfect for casual cold days.', 'بلوفر زيتي أوفرسايز بخامة تريكو بارزة وأطراف مضلعة ينفع لمشاوير الشتا اليومية.', 'An olive-green oversized crew-neck sweater in textured knit fabric with long drop-shoulder sleeves and ribbed neckline, cuffs, and hem.', 'UNISEX', 'ACTIVE', 55000, '/products/product-19-6.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-7', 'merchant-19', 'category-jeans', 'Burgundy High Waisted Cropped Jeans', 'جينز نبيتي هاي ويست كروب', 'High-waisted burgundy cropped jeans with straight legs and five pockets for daily wear.', 'جينز نبيتي بوسط عالي ورجل عدلة قصيرة وخمس جيوب تلبسيه في المشاوير اليومية.', 'High-waisted burgundy straight-leg cropped denim jeans with a button and zip fly, belt loops, and classic five-pocket styling.', 'UNISEX', 'ACTIVE', 75000, '/products/product-19-7.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-8', 'merchant-19', 'category-pants', 'Grey Drawstring Cargo Pants', 'بنطلون كارغو رمادي برباط', 'Washed grey loose cotton pants with flap cargo pockets and cuffed hems for daily casual wear.', 'بنطلون قطن رمادي مغسول واسع بجيوب كارغو بقلاب ورجل مقفولة للبس الكاجوال كل يوم.', 'Washed gray loose-fit cotton-twill cargo pants with an elastic drawstring waist, front pleats, large flap cargo pockets on the thighs, slanted side pockets, and cuffed hems.', 'MEN', 'ACTIVE', 65000, '/products/product-19-8.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-9', 'merchant-19', 'category-dresses', 'Brown Linen Button-Front Dress', 'فستان كتان بني بزراير من قدام', 'A brown linen two-piece-look dress with puff sleeves, ideal for casual daytime wear.', 'فستان كتان بني شكله زي طقم قطعتين بأكمام منفوشة، مناسب لخروجات النهار الكاجوال.', 'A brown linen two-piece style button-front dress with a cropped boxy short puff-sleeve collared shirt top with button-tab cuffs and a matching A-line mini skirt with side pockets.', 'WOMEN', 'ACTIVE', 110000, '/products/product-19-9.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-19-10', 'merchant-19', 'category-skirts', 'Cream Linen Drawstring Skirt', 'جيبة كريمي كتان برباط', 'A flowy off-white linen maxi skirt with a drawstring waist and side pockets, perfect for casual summer days.', 'جيبة ماكسي كتان أوف وايت واسعة بوسط برباط وجيوب من الجنب تنفع لخروجات الصيف.', 'An off-white linen maxi skirt with a gathered full A-line cut, elastic waistband with front drawstring tie, and two large side patch pockets.', 'WOMEN', 'ACTIVE', 30000, '/products/product-19-10.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-1', 'merchant-20', 'category-bags', 'Beige Boxy Sherpa Tote Bag', 'شنطة توت بيج شيربا بوكسي', 'Boxy beige sherpa tote with puffy horizontal stitching and short handles for casual daily wear.', 'شنطة توت بيج بوكسي بخامة شيربا وخياطة عريضة منفوخة وايد قصيرة تنفع للبس اليومي الكاجوال.', 'A beige boxy structured tote handbag with short top handles crafted from plush teddy sherpa fleece featuring horizontal quilted puffy stitching.', 'WOMEN', 'ACTIVE', 60000, '/products/product-20-1.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-2', 'merchant-20', 'category-jackets', 'Navy Two-Button Notch Lapel Jacket', 'جاكيت كحلي بياقة ريفير بزرارين', 'A dark navy blazer with notch lapels and flap pockets, ideal for work and formal occasions.', 'بليزر كحلي غامق بياقة ريفير وجيوب بغطا، مناسب للشغل والمناسبات الرسمية.', 'A dark navy single-breasted tailored blazer jacket in a soft matte fabric with notch lapels, a two-button front closure, two button-flap chest pockets, two flap lower patch pockets, and long sleeves with buttoned cuffs.', 'UNISEX', 'ACTIVE', 70000, '/products/product-20-2.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-3', 'merchant-20', 'category-hoodies', 'Olive Fleece Drawstring Hoodie', 'هودي زيتي فليس برباط', 'Relaxed olive fleece pullover with drawstring hood and kangaroo pocket for daily cold-weather wear.', 'هودي زيتي مريح بخامة فليس ناعمة وكابيشو برباط وجيب أمامي تلبسه كل يوم في البرد.', 'Olive green pullover hoodie in soft fleece fabric with a relaxed cut, drawstring hood, long sleeves with ribbed cuffs, front kangaroo pocket, and ribbed hem.', 'UNISEX', 'ACTIVE', 55000, '/products/product-20-3.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-4', 'merchant-20', 'category-sweatshirts', 'Burgundy Relaxed Ribbed Sweatshirt', 'سويت شيرت نبيتي مريح مضلع', 'A burgundy long-sleeve sweatshirt with ribbed neck, cuffs and hem for daily casual wear.', 'سويت شيرت نبيتي بكم طويل ورقبة واساور مضلعين للبس الكاجوال اليومي.', 'A burgundy long-sleeve crewneck sweatshirt with a relaxed cut in soft sweatshirt-knit fabric featuring a ribbed crew neckline, ribbed cuffs, ribbed hem, and a plain front.', 'UNISEX', 'ACTIVE', 55000, '/products/product-20-4.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-5', 'merchant-20', 'category-knitwear', 'Grey Nubby Knit Sweater', 'سويتر رمادي تريكو بارز', 'Heather gray crewneck sweater in nubby textured knit with ribbed trims, good for everyday casual wear.', 'سويتر رمادي برقبة مدورة ونسيج تريكو بارز مع أستك مضلع، مناسب للبس اليومي الكاجوال.', 'A heather gray crewneck sweater with a relaxed long-sleeve cut in textured nubby knit fabric with ribbed crew neckline, cuffs, and hem.', 'UNISEX', 'ACTIVE', 80000, '/products/product-20-5.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-6', 'merchant-20', 'category-jeans', 'Brown Straight-Leg Five-Pocket Jeans', 'جينز بني ستريت بخمس جيوب', 'Washed brown straight-leg jeans with five pockets and a button closure for daily casual outfits.', 'جينز بني مغسول برجل ستريت وخمس جيوب بقفل زراير للبس الكاجوال كل يوم.', 'Brown straight-leg five-pocket jeans in washed brown denim fabric with button closure, belt loops, front scoop pockets and a small coin pocket.', 'UNISEX', 'ACTIVE', 100000, '/products/product-20-6.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-7', 'merchant-20', 'category-pants', 'Cream Sherpa Fleece Jogger Pants', 'بنطلون جوجر شيربا فليس كريمي', 'Fuzzy cream sherpa joggers with drawstring waist, side pockets and ribbed cuffs for cold casual days.', 'بنطلون جوجر كريمي بخامة شيربا فرو ناعمة ووسط برباط وجيوب وكاحل مضلع للبس اليومي في الشتا.', 'Cream-colored fuzzy sherpa fleece jogger sweatpants with a relaxed tapered cut, elastic drawstring waistband, side pockets, and ribbed ankle cuffs.', 'MEN', 'ACTIVE', 45000, '/products/product-20-7.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-8', 'merchant-20', 'category-dresses', 'Black Patch Pocket Dress', 'فستان اسود بجيوب خارجية', 'A relaxed black knee-length shirt dress with front buttons and patch pockets for daily outings.', 'فستان قميص اسود مريح لحد الركبة بزراير وجيوب خارجية للخروجات اليومية.', 'Black long-sleeve shirt dress in textured linen fabric with a relaxed straight knee-length cut, pointed collar, front button placket, cuffed sleeves, and two patch pockets.', 'WOMEN', 'ACTIVE', 90000, '/products/product-20-8.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-9', 'merchant-20', 'category-skirts', 'Beige Ribbed Knit Midi Skirt', 'جيبة بيج تريكو مضلعة ميدي', 'Light beige straight midi skirt in soft ribbed knit with a wide waistband for easy everyday wear.', 'جيبة بيج فاتحة بقصة مستقيمة ميدي بخامة تريكو مضلعة ناعمة ووسط عريض تنفع لمشاوير كل يوم', 'A light beige knit midi skirt with a straight long cut, soft ribbed knit fabric, wide ribbed waistband, all-over vertical ribbed texture, and ribbed hem.', 'WOMEN', 'ACTIVE', 55000, '/products/product-20-9.jpg');
INSERT OR REPLACE INTO products (id, merchantId, categoryId, nameEn, nameAr, descriptionEn, descriptionAr, visualDescription, gender, status, pricePiasters, imagePath) VALUES ('product-20-10', 'merchant-20', 'category-shoes', 'Navy Canvas Lace Up Sneakers', 'سنيكرز قماش كحلي برباط', 'Low-top navy canvas sneakers with laces and off-white sole for everyday wear.', 'سنيكرز قماش كحلي واطي برباط ونعل أوف وايت مناسب للبس كل يوم.', 'Navy blue low-top lace-up canvas sneaker with matching navy laces tied in a bow, metal eyelets, stitched rounded toe cap, and off-white rubber sole.', 'UNISEX', 'ACTIVE', 125000, '/products/product-20-10.jpg');
